import { describe, expect, it } from 'vitest';
import { createSim, getSnapshot, injectEvent, makeGridGraph, setControl, step, type Sim } from './sim';
import * as C from './config';

const DT = 0.5;
const ROOT = 1;
const ORDINARY = [2, 4, 3, 6, 9, 18];
const STREETS = [[5, 6, 11], [10, 11, 16], [15, 16, 21], [6, 7, 12], [11, 12, 17], [16, 17, 22]];

// A controlled queue snapshot: all requests below are generated by the real stop-line rules.
// The six older ordinary queues have more followers than the ambulance queue, so WSPT has
// genuine competing work. Every policy gets exactly the same vehicles and external outage.
function scenario(mode: 'FIFO' | 'DARKGRID' = 'DARKGRID', enabled = true) {
  const sim = createSim(makeGridGraph(5), 23, mode, { directEmergencyPriority: enabled });
  for (const lane of sim.lanes) lane.cars = [];
  for (const a of sim.agents) { a.place = 'OFF'; a.requestId = null; a.held = false; }
  sim.plannedFaults = [];
  injectEvent(sim, { type: 'OUTAGE', radiusM: 10000, restoreAfterS: 10000 });
  sim.t = 60; // Start the fixture when the rescue is being dispatched, with no prior traffic run.
  sim.ambRoute = [];
  setControl(sim, 'MANUAL'); // Build the initial backlog before the first automatic assignment.
  const lane = (from: number, to: number) => sim.laneByStep.get(from + '>' + to)!;
  const place = (id: number, from: number, to: number, next: number, position?: number) => {
    const a = sim.agents[id], road = lane(from, to), out = lane(to, next);
    Object.assign(a, { place: 'ROAD', lane: road.id, s: position ?? road.len, speed: 0,
      route: [out], dest: next, held: false, requestId: null, stoppedS: 0, arrivedT: null,
      fault: null, yieldStartT: null, exitBlockedSince: null, type: 'PASSENGER' });
    a.known.clear(); a.grants.clear(); road.occluded = false; road.cars.push(a);
    road.cars.sort((a, b) => b.s - a.s);
    return a;
  };
  STREETS.forEach(([from, to, next], i) => {
    place(ORDINARY[i], from, to, next);
    for (let k = 0; k < 13; k++) place(100 + i * 13 + k, from, to, next, 250 - C.GAP_M * (k + 1));
  });
  step(sim, DT);
  for (const id of ORDINARY) expect(sim.requests.get(sim.agents[id].requestId!)?.cause).toBe('MISSING_OUTAGE_INFO');
  const root = place(ROOT, 0, 1, 6);
  const road = lane(0, 1);
  const route = [road, lane(1, 2), lane(2, 3), lane(3, 4), lane(4, 9), lane(9, 14), lane(14, 19), lane(19, 24)];
  Object.assign(sim.amb, { place: 'ROAD', lane: road.id, s: road.len - C.GAP_M, speed: 0,
    route: route.slice(1), dest: 24, arrivedT: null });
  sim.ambRoute = route; sim.dispatchT = sim.t; sim.mission.phase = 'TO_HOSPITAL';
  road.cars.push(sim.amb); road.cars.sort((a, b) => b.s - a.s);
  step(sim, DT);
  const request = root.requestId!;
  expect(sim.requests.get(request)?.cause).toBe('MISSING_OUTAGE_INFO');
  return { sim, root, road, request, place, lane };
}

const assignedTo = (sim: Sim, id: string) => sim.operators.find(o => o.job?.requestIds.includes(id));
const assign = (sim: Sim) => { setControl(sim, 'AUTO'); step(sim, DT); };

function measure(mode: 'FIFO' | 'DARKGRID', enabled: boolean) {
  const { sim, root, road, request } = scenario(mode, enabled);
  const start = sim.t, initialS = sim.amb.s, ordinaryIds = new Set(ORDINARY.map(id => sim.agents[id].requestId!));
  const waits: number[] = [];
  let assigned: number | null = null, cleared: number | null = null, stopped = 0, busy = 0;
  setControl(sim, 'AUTO');
  for (let i = 0; i < 1200; i++) {
    const old = sim.operators.map(o => o.job);
    busy += sim.operators.filter(o => o.job).length * DT;
    step(sim, DT);
    for (const lane of sim.lanes) for (let k = 1; k < lane.cars.length; k++) {
      expect(lane.cars[k - 1].s - lane.cars[k].s).toBeGreaterThanOrEqual(C.GAP_M - 1e-6);
    }
    if (assigned === null && assignedTo(sim, request)) assigned = sim.t - start;
    if (cleared === null && !road.cars.includes(root)) cleared = sim.t - start;
    if (sim.arriveT === null && (sim.amb.place !== 'ROAD' || sim.amb.speed < 0.1)) stopped += DT;
    sim.operators.forEach((o, k) => {
      if (o.job && o.job !== old[k]) for (const id of o.job.requestIds) {
        if (ordinaryIds.has(id)) { const r = sim.requests.get(id)!; waits.push(sim.t - r.createdAt); ordinaryIds.delete(id); }
      }
    });
  }
  waits.sort((a, b) => a - b);
  return { mode, enabled, assignedAfterS: assigned, clearedAfterS: cleared, ambulanceStoppedS: stopped,
    ambulanceTripS: sim.metrics.ambulanceTripS, arrivalAt: sim.arriveT, blockingVehMin: sim.blockingVehMin,
    initialOrdinaryP95S: waits[Math.ceil(waits.length * 0.95) - 1], initialOrdinaryAssigned: waits.length,
    initialOrdinaryMeanS: waits.reduce((sum, w) => sum + w, 0) / waits.length,
    operatorBusyS: busy, ambulanceMoved: sim.amb.lane !== road.id || sim.amb.s > initialS };
}

describe('direct actionable emergency blocker priority', () => {
  it('selects the physical information root and clears the actual lane after normal service', () => {
    const { sim, root, road, request } = scenario();
    const before = sim.amb.s;
    assign(sim);
    const op = assignedTo(sim, request)!;
    expect(op).toBeDefined();
    expect(op.doneT - sim.t).toBe(30);
    expect(sim.amb.s).toBe(before);
    step(sim, 29.5);
    expect(road.cars.includes(root)).toBe(true);
    step(sim, 0.5);
    expect(root.known.has(road.to)).toBe(true);
    step(sim, 0.5);
    expect(road.cars.includes(root)).toBe(false);
    step(sim, 0.5);
    expect(sim.amb.s).toBeGreaterThan(before);
  });

  it('traces past an ordinary queued follower without prioritizing its STUCK request', () => {
    const { sim, road, request, place } = scenario();
    const follower = place(50, 0, 1, 6, road.len - C.GAP_M);
    // An occupied curb prevents autonomous pull-over; the follower must wait for the root.
    const curb = sim.agents[51];
    Object.assign(curb, { place: 'CURB', lane: road.id, s: follower.s, boxNode: road.to, yieldStartT: sim.t });
    sim.nodes.get(road.to)!.curb.push(curb);
    sim.amb.s -= C.GAP_M;
    road.cars.sort((a, b) => b.s - a.s);
    step(sim, C.STUCK_TIMEOUT_S);
    const followerRequest = follower.requestId!;
    expect(sim.requests.get(followerRequest)?.cause).toBe('STUCK');
    assign(sim);
    expect(assignedTo(sim, request)).toBeDefined();
    expect(assignedTo(sim, followerRequest)).toBeUndefined();
  });

  it.each(['full exit', 'closed exit', 'fault', 'invalid request', 'occlusion', 'moving ambulance', 'gap', 'intersection occupied', 'headway'])(
    'does not promote an unproven root: %s', condition => {
      const { sim, root, road, request, place } = scenario();
      if (condition === 'full exit') place(50, 1, 6, 11, 0);
      if (condition === 'closed exit') injectEvent(sim, { type: 'COLLISION', edgeId: root.route[0].edgeId });
      if (condition === 'fault') root.fault = { hard: true, towAt: null };
      if (condition === 'invalid request') sim.requests.get(request)!.cause = 'STUCK';
      if (condition === 'occlusion') road.occluded = true;
      if (condition === 'moving ambulance') sim.amb.s -= 20;
      if (condition === 'gap') { sim.amb.s -= 20; root.speed = 0; }
      if (condition === 'intersection occupied') {
        const occupant = sim.agents[51];
        Object.assign(occupant, { place: 'BOX', boxNode: road.to, requestId: 'waiting-in-box' });
        sim.nodes.get(road.to)!.box.push(occupant);
      }
      if (condition === 'headway') sim.nodes.get(road.to)!.nextPassT = sim.t + 20;
      assign(sim);
      expect(assignedTo(sim, request)).toBeUndefined();
    });

  it('does not promote a root whose request has disappeared', () => {
    const { sim, root, request } = scenario();
    sim.requests.delete(request);
    assign(sim);
    expect(assignedTo(sim, request)).toBeUndefined();
    expect(root.requestId).toBe(request); // Deliberately inconsistent fixture must not be trusted.
  });

  it('does not confuse an opposite-direction lane with the same edge ID', () => {
    const { sim, road, request, lane } = scenario();
    const reverse = lane(1, 0);
    expect(reverse.edgeId).toBe(road.edgeId);
    road.cars = road.cars.filter(a => a !== sim.amb);
    reverse.cars.push(sim.amb); sim.amb.lane = reverse.id; sim.amb.s = 100;
    sim.amb.route = [lane(0, 5)]; sim.ambRoute = [reverse, ...sim.amb.route];
    assign(sim);
    expect(assignedTo(sim, request)).toBeUndefined();
  });

  it('reevaluates unassigned jobs after the ambulance moves to a different route', () => {
    const { sim, road, request, lane } = scenario();
    expect(sim.jobs.find(j => j.kind !== 'ZONE_POLICY')!.requestIds).toContain(request);
    road.cars = road.cars.filter(a => a !== sim.amb);
    const other = lane(20, 21);
    other.cars.push(sim.amb); sim.amb.lane = other.id; sim.amb.s = 100;
    sim.amb.route = [lane(21, 22)]; sim.ambRoute = [other, ...sim.amb.route];
    assign(sim);
    expect(assignedTo(sim, request)).toBeUndefined();
  });

  it('does not interrupt a valid job already assigned to an operator', () => {
    const { sim, request } = scenario('DARKGRID', false);
    assign(sim);
    expect(assignedTo(sim, request)).toBeUndefined();
    const old = sim.operators.map(o => ({ job: o.job, doneT: o.doneT }));
    sim.directEmergencyPriority = true;
    step(sim, DT);
    sim.operators.forEach((o, i) => { expect(o.job).toBe(old[i].job); expect(o.doneT).toBe(old[i].doneT); });
  });

  it('with the switch disabled keeps the current DG ordering of five older, higher-impact jobs', () => {
    const { sim, request } = scenario('DARKGRID', false);
    assign(sim);
    expect(sim.operators.map(o => o.job?.requestIds)).toEqual([['r1'], ['r2'], ['r3'], ['r4'], ['r5']]);
    expect(assignedTo(sim, request)).toBeUndefined();
    step(sim, 29.5);
    expect(assignedTo(sim, request)).toBeUndefined();
    step(sim, DT);
    expect(assignedTo(sim, request)).toBeDefined();
  });

  it('preserves batching and the original 45-second deadline for an emergency batch', () => {
    const { sim, request, place } = scenario();
    const member = place(50, 6, 1, 2);
    // Create a compatible request by the normal stop-line transition before automatic dispatch.
    step(sim, DT);
    expect(sim.requests.get(member.requestId!)?.cause).toBe('MISSING_OUTAGE_INFO');
    assign(sim);
    const op = assignedTo(sim, request)!;
    expect(op.job?.kind).toBe('BATCH');
    expect(op.job?.requestIds).toHaveLength(2);
    expect(op.doneT - sim.t).toBe(45);
    const job = op.job;
    step(sim, 44.5);
    expect(op.job).toBe(job);
    step(sim, DT);
    expect(sim.requests.has(request)).toBe(false);
  });

  it('keeps Phase 1A cleanup when an emergency request becomes stale', () => {
    const { sim, road, request } = scenario();
    assign(sim);
    const op = assignedTo(sim, request)!;
    sim.outage!.restoreAt = sim.t + DT;
    sim.restoreTimes.set(road.to, sim.t + DT);
    step(sim, DT);
    expect(sim.requests.has(request)).toBe(false);
    expect(op.job?.requestIds.includes(request) ?? false).toBe(false);
  });

  it('leaves FIFO unchanged even when the experimental switch is requested', () => {
    const a = scenario('FIFO', false).sim, b = scenario('FIFO', true).sim;
    setControl(a, 'AUTO'); setControl(b, 'AUTO');
    for (let i = 0; i < 300; i++) { step(a, DT); step(b, DT); }
    expect(getSnapshot(b)).toEqual(getSnapshot(a));
    expect(b.directEmergencyPriority).toBe(false);
  });

  it('measures FIFO, current DG and enabled DG on identical physical queues', () => {
    const results = [measure('FIFO', false), measure('DARKGRID', false), measure('DARKGRID', true)];
    console.info('PHASE_1B_MEASUREMENTS ' + JSON.stringify(results));
    const [fifo, current, enabled] = results;
    for (const r of results) { expect(r.ambulanceMoved).toBe(true); expect(r.arrivalAt).not.toBeNull(); expect(r.initialOrdinaryAssigned).toBe(6); }
    expect(enabled.assignedAfterS!).toBeLessThan(current.assignedAfterS!);
    expect(enabled.clearedAfterS!).toBeLessThan(current.clearedAfterS!);
    expect(enabled.ambulanceStoppedS).toBeLessThan(current.ambulanceStoppedS);
    expect(enabled.ambulanceTripS!).toBeLessThan(fifo.ambulanceTripS!);
  });
});
